/* ------------------------------------------------------------------
 * 설교 마인드맵 (Sermon Mindmap) — Obsidian plugin
 * 설교문(마크다운)과 마인드맵을 한 파일로 오가며 편집합니다.
 * Phase 1: 문서 ↔ 마인드맵 전환, 맵 렌더링, 맵에서 구조 편집
 * ------------------------------------------------------------------ */
'use strict';

const obsidian = require('obsidian');
const { Plugin, TextFileView, Notice, Menu, Scope, SuggestModal, FuzzySuggestModal, MarkdownRenderer, Modal, PluginSettingTab, Setting, setIcon, MarkdownView } = obsidian;

const BIBLE_FINDER_ID = 'obsidian-bible-finder';
const SMM_BUILD = '2026-10-03-ipadfont';

const VIEW_TYPE = 'sermon-mindmap-view';

/**
 * 가지(줄기) 색 — 다크 모드에서 눈이 편하도록 채도를 낮춘 8색.
 * 제목(H1~H6)에 쓰는 색 6개에, 비어 있던 초록·장미빛 두 자리를 채워 만들었다.
 * 따뜻한 색과 차가운 색이 번갈아 오도록 순서를 잡아, 옆에 붙은 가지끼리
 * 절대 헷갈리지 않게 함(이웃 간 최소 색차 42.6 — 원래 순서는 13.8이었음).
 * 배경(#262626) 대비는 모두 5.27:1 이상이라 얇은 선도 또렷하게 보인다.
 */
const BRANCH_COLORS = [
  '#F0BC66', // 금빛
  '#A9B4B0', // 세이지
  '#E3A263', // 호박
  '#8FA6C2', // 청색
  '#D08F7C', // 테라코타
  '#9B93BE', // 연보라
  '#8FBE93', // 초록
  '#DE93A4', // 장미
];

const H_GAP = 56;   // 부모-자식 가로 간격
const V_GAP = 12;   // 형제 세로 간격
const PAD = 60;     // 전체 여백
const NEW_TEXT = '새 항목';
const NEW_BODY = '새 문단';

/* ================= 마크다운 구조 파서 ================= */

/* ========== 노드 명암 (배경 음영) 및 줄머리 기호 상수 & 헬퍼 ========== */
const SMM_SHADE_RE = /[ \t]*%%shade:([roygbp])([123])%%[ \t]*$/;

const SMM_DOCX_SHADE_COLORS = {
  r1: 'FDE8E8', r2: 'FCD0D0', r3: 'F9A8A8',
  o1: 'FEEEDD', o2: 'FDDDBB', o3: 'FBC188',
  y1: 'FFF9D1', y2: 'FFF3A3', y3: 'FFE066',
  g1: 'DFF5E2', g2: 'BFEBC4', g3: '8FD99B',
  b1: 'DEF0FF', b2: 'BDE0FF', b3: '8CC8FF',
  p1: 'EEE5FF', p2: 'DCCBFF', p3: 'BFA6FF',
};

function smmGetShadeInfo(text) {
  if (!text) return null;
  const m = String(text).match(SMM_SHADE_RE);
  if (!m) return null;
  return {
    color: m[1],
    level: m[2],
    token: m[0].trim(),
    cleanText: String(text).replace(SMM_SHADE_RE, ''),
  };
}

function smmGetDocxShadeColor(color, level) {
  if (!color || !level) return null;
  return SMM_DOCX_SHADE_COLORS[color + level] || null;
}

function smmEscapeRegExp(s) {
  return String(s || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const SMM_SUB_MARKS_LIST = [
  '→', '←', '↑', '↓', '↔', '↕', '↗', '↙', '↖', '↘', '➔', '➡', '⇒', '⇐', '⇨', '⇦'
];
const SMM_SUB_MARKS_SET = new Set(SMM_SUB_MARKS_LIST);

const SMM_TRIANGLE_MARKS = ['▶', '▷', '◀', '◁', '▲', '△', '▼', '▽'];
const SMM_HANJA_M_MARKS = [
  '＃', '＆', '＊', '＠', '§', '※', '☆', '★', '○', '●',
  '◎', '◇', '◆', '□', '■', '〓', '♤',
  '♠', '♡', '♥', '♧', '♣', '⊙', '◈', '▣', '◐', '◑',
  '▒', '▤', '▥', '▨', '▧', '▦', '▩', '♨', '☏', '☎',
  '☜', '☞', '¶', '†', '‡',
  '♭', '♩', '♪', '♬', '㉿', '㈜', '№', '㏇', '™', '㏂',
  '㏘', '℡', '®', 'ª', 'º'
];
const SMM_STRONG_MARKS_LIST = ['✓', '✔'].concat(SMM_TRIANGLE_MARKS, SMM_HANJA_M_MARKS);
const SMM_DEFAULT_STRONG_MARKS = new Set(SMM_STRONG_MARKS_LIST.concat(['v', 'V']));
const SMM_ALL_EXPLICIT_MARKS = Array.from(new Set(SMM_STRONG_MARKS_LIST.concat(SMM_SUB_MARKS_LIST)));
const SMM_LINE_EXPLICIT_MARK_RE = new RegExp('^([ \\t]*)([' + SMM_ALL_EXPLICIT_MARKS.map(smmEscapeRegExp).join('') + '])([ \\t]*)(.*)$');
const SMM_EXPLICIT_NUM_MARK_RE = /^([ \t]*)(?:[✓✔][ \t]+)(\d{1,2}[.)])([ \t]+)(.*)$/;
const SMM_KOR_OUTLINE_SEQ = '가나다라마바사아자차카타파하';
const SMM_OUTLINE_STYLES = [
  { id: 'num_dot',    label: '1. 2. 3.',      explicitPrefix: '✓ ' },
  { id: 'half_paren', label: '1) 2) 3)',      explicitPrefix: '✓ ' },
  { id: 'full_paren', label: '(1) (2) (3)',   explicitPrefix: '' },
  { id: 'circled',    label: '① ② ③',         explicitPrefix: '' },
  { id: 'kor_dot',    label: '가. 나. 다.',   explicitPrefix: '' },
  { id: 'kor_paren',  label: '(가) (나) (다)', explicitPrefix: '' },
  { id: 'kor_half',   label: '가) 나) 다)',   explicitPrefix: '' },
  { id: 'cap_alpha',  label: 'A. B. C.',      explicitPrefix: '' },
  { id: 'low_alpha',  label: 'a. b. c.',      explicitPrefix: '' },
];

function smmIsOutlineMarkToken(markChar) {
  if (!markChar) return false;
  return /^(?:\d{1,2}[.)]|\(\d{1,2}\)|[①-⑳]|[가나다라마바사아자차카타파하][.)]|\([가나다라마바사아자차카타파하]\)|[A-Za-z]\.)$/.test(String(markChar));
}

function smmIsWideMark(markChar) {
  const s = String(markChar || '');
  return s.length > 1 || /^[①-⑳]$/.test(s);
}

function smmParseOutlinePrefix(rawBody) {
  if (!rawBody) return null;
  const s = String(rawBody);
  if (typeof smmIsVerseEditorLine === 'function' && smmIsVerseEditorLine(s)) return null;
  let m;
  if ((m = s.match(/^([①-⑳])([ \t]*)(.+)$/))) {
    return { family: 'circled', mark: m[1], rawLen: m[1].length + m[2].length, body: m[3], ordinal: m[1].charCodeAt(0) - 0x2460 + 1 };
  }
  if ((m = s.match(/^(\(\d{1,2}\))([ \t]+)(.+)$/))) {
    return { family: 'full_paren', mark: m[1], rawLen: m[1].length + m[2].length, body: m[3], ordinal: parseInt(m[1].slice(1, -1), 10) };
  }
  if ((m = s.match(/^(\([가나다라마바사아자차카타파하]\))([ \t]+)(.+)$/))) {
    return { family: 'kor_paren', mark: m[1], rawLen: m[1].length + m[2].length, body: m[3], ordinal: SMM_KOR_OUTLINE_SEQ.indexOf(m[1][1]) + 1 };
  }
  if ((m = s.match(/^([가나다라마바사아자차카타파하]\.)([ \t]+)(.+)$/))) {
    return { family: 'kor_dot', mark: m[1], rawLen: m[1].length + m[2].length, body: m[3], ordinal: SMM_KOR_OUTLINE_SEQ.indexOf(m[1][0]) + 1 };
  }
  if ((m = s.match(/^([가나다라마바사아자차카타파하]\))([ \t]+)(.+)$/))) {
    return { family: 'kor_half', mark: m[1], rawLen: m[1].length + m[2].length, body: m[3], ordinal: SMM_KOR_OUTLINE_SEQ.indexOf(m[1][0]) + 1 };
  }
  if ((m = s.match(/^([A-Z]\.)([ \t]+)(.+)$/)) && !/^[A-Z]\./.test(m[3])) {
    return { family: 'cap_alpha', mark: m[1], rawLen: m[1].length + m[2].length, body: m[3], ordinal: m[1].charCodeAt(0) - 64 };
  }
  if ((m = s.match(/^([a-z]\.)([ \t]+)(.+)$/)) && !/^[a-z]\./.test(m[3])) {
    return { family: 'low_alpha', mark: m[1], rawLen: m[1].length + m[2].length, body: m[3], ordinal: m[1].charCodeAt(0) - 96 };
  }
  return null;
}

function smmFormatOutlineToken(styleId, index1Based) {
  const n = Math.max(1, Number(index1Based) || 1);
  switch (styleId) {
    case 'num_dot': return `${n}.`;
    case 'half_paren': return `${n})`;
    case 'full_paren': return `(${n})`;
    case 'circled': return n <= 20 ? String.fromCharCode(0x2460 + n - 1) : `(${n})`;
    case 'kor_dot': return `${SMM_KOR_OUTLINE_SEQ[(n - 1) % SMM_KOR_OUTLINE_SEQ.length]}.`;
    case 'kor_paren': return `(${SMM_KOR_OUTLINE_SEQ[(n - 1) % SMM_KOR_OUTLINE_SEQ.length]})`;
    case 'kor_half': return `${SMM_KOR_OUTLINE_SEQ[(n - 1) % SMM_KOR_OUTLINE_SEQ.length]})`;
    case 'cap_alpha': return `${String.fromCharCode(65 + ((n - 1) % 26))}.`;
    case 'low_alpha': return `${String.fromCharCode(97 + ((n - 1) % 26))}.`;
    default: return `${n}.`;
  }
}

function smmParseExplicitMarkLine(line) {
  if (!line) return null;
  const s = String(line);
  const nm = s.match(SMM_EXPLICIT_NUM_MARK_RE);
  if (nm) {
    const indent = nm[1];
    const mark = nm[2];
    const body = nm[4] || '';
    const rawLen = s.length - indent.length - body.length;
    const family = mark.endsWith(')') ? 'half_paren' : 'num_dot';
    const ordinal = parseInt(mark, 10) || 1;
    return { indent, mark, body, rawLen, explicitNum: true, family, ordinal };
  }
  const m = s.match(SMM_LINE_EXPLICIT_MARK_RE);
  if (!m) return null;
  const indent = m[1];
  const mark = m[2];
  const trailingWs = m[3] || '';
  const body = m[4] || '';
  const rawLen = mark.length + trailingWs.length;
  return { indent, mark, body, rawLen };
}

function smmGetLineMarks(cfg) {
  return [
    (cfg && cfg.markStrongIcon) || '✓',
    (cfg && cfg.markMidIcon) || 'ㆍ',
    (cfg && cfg.markSubIcon) || '-',
  ];
}

function smmIsStrongMark(ch, cfg) {
  if (!ch) return false;
  const markChar = typeof ch === 'object' ? ch.mark : ch;
  if (SMM_SUB_MARKS_SET.has(markChar)) return false;
  if (smmIsOutlineMarkToken(markChar)) return true;
  const target = (cfg && cfg.markStrongIcon) || '✓';
  if (markChar === target) return true;
  return SMM_DEFAULT_STRONG_MARKS.has(markChar);
}

function smmHangCharsFor(markCh, isNumbered, cfg) {
  if (!markCh) return 0;
  const ch = typeof markCh === 'object' ? markCh.mark : markCh;
  if (isNumbered) return Math.max(1.7, String(ch).length * 0.72);
  if (smmIsOutlineMarkToken(ch)) return Math.max(1.5, String(ch).length * 0.72);
  if (smmIsStrongMark(ch, cfg)) return 1.0;
  if (ch === '-') return 1.1;
  return 1.0;
}

function indentWidth(s) {
  let w = 0;
  for (const ch of s) w += ch === '\t' ? 4 : 1;
  return w;
}

/**
 * 문서를 트리로 파싱한다.
 * - 제목(H1~H6)이 큰 가지, 목록(-, *, +, 1.)이 잔가지
 * - frontmatter(---)와 코드 블록(```)은 건너뜀
 * - 제목/목록이 아닌 본문 문단은 맵에 노드로 띄우지 않는다(설교 본문 보호)
 */
function parseDoc(text) {
  const lines = String(text == null ? '' : text).split(/\r?\n/);
  const root = { kind: 'root', text: '', line: -1, headingLevel: 0, children: [], parent: null };
  const all = [];

  // frontmatter 범위
  let fmEnd = -1;
  if (lines[0] === '---') {
    for (let j = 1; j < lines.length; j++) {
      const t = lines[j].trim();
      if (t === '---' || t === '...') { fmEnd = j; break; }
    }
  }

  let inFence = false;
  const headingStack = [root];
  let listStack = [];
  let lastBody = null; // 직전에 확정된 본문 문단 (붙여 쓴 목록의 부모 판정용)
  let pendingBlank = false; // 직전 줄이 빈 줄이었는지

  // 본문 문단 버퍼 → "본문(body)" 노드. 빈 줄마다 별개의 문단으로 나뉜다.
  // 들여쓴 문단은 해당 목록 항목의 본문, 아니면 현재 제목의 본문
  let buf = null; // { container, start, arr }
  const flush = () => {
    if (!buf) return;
    let a = 0, b = buf.arr.length - 1;
    while (a <= b && buf.arr[a].trim() === '') a++;
    while (b >= a && buf.arr[b].trim() === '') b--;
    if (a <= b) {
      const ind = (buf.arr[a].match(/^[ \t]*/) || [''])[0];
      const rawBodyText = buf.arr.slice(a, b + 1).map((l) => (l.startsWith(ind) ? l.slice(ind.length) : l)).join('\n');
      const sm = smmGetShadeInfo(rawBodyText);
      const nodeText = sm ? sm.cleanText : rawBodyText;
      const node = {
        kind: 'body',
        text: nodeText,
        bodyIndent: ind,
        line: buf.start + a,
        endLine: buf.start + b,
        children: [], parent: buf.container, headingLevel: 99,
      };
      if (sm) node.shade = { color: sm.color, level: sm.level, token: sm.token };
      buf.container.children.push(node);
      all.push(node);
      lastBody = node;
    }
    buf = null;
  };
  const computeContainer = (line) => {
    let container = headingStack[headingStack.length - 1];
    if (/^[ \t]/.test(line) && listStack.length) {
      const li = indentWidth((line.match(/^[ \t]*/) || [''])[0]);
      for (let k = listStack.length - 1; k >= 0; k--) {
        if (listStack[k].w < li) { container = listStack[k].node; break; }
      }
    }
    return container;
  };
  const bufPush = (i, line, container) => {
    if (buf && container && buf.container !== container) flush();
    if (!buf) buf = { container: container || headingStack[headingStack.length - 1], start: i, arr: [] };
    buf.arr.push(line);
  };
  /**
   * 빈 줄 뒤에 폭 w로 돌아온 줄(목록 항목이든 본문 문단이든)의 진짜 조상을 찾기 위해,
   * 그보다 얕지 않은(=같은 급이거나 그 안쪽으로 취급되는) 스택 항목들을 걷어낸다.
   * '본문에 붙여쓴 목록'의 기준점(isBody)은 원래 폭보다 1 낮게 저장돼 있으므로 +1 보정한다.
   */
  const popStaleForBlankReturn = (w) => {
    while (listStack.length) {
      const top = listStack[listStack.length - 1];
      const stillCovers = top.isBody ? (w <= top.w + 1) : (top.w >= w);
      if (!stillCovers) break;
      listStack.pop();
    }
  };

  for (let i = 0; i < lines.length; i++) {
    if (fmEnd >= 0 && i <= fmEnd) continue;
    const line = lines[i];

    if (/^\s*(`{3,}|~{3,})/.test(line)) { inFence = !inFence; bufPush(i, line, computeContainer(line)); continue; }
    if (inFence) { bufPush(i, line, null); continue; }

    // 제목
    let m = line.match(/^(#{1,6})\s+(.+)$/);
    if (m) {
      flush();
      const level = m[1].length;
      while (headingStack.length > 1 && headingStack[headingStack.length - 1].headingLevel >= level) {
        headingStack.pop();
      }
      const parent = headingStack[headingStack.length - 1];
      const sm = smmGetShadeInfo(m[2]);
      const nodeText = (sm ? sm.cleanText : m[2]).trim();
      const node = { kind: 'heading', headingLevel: level, text: nodeText, line: i, children: [], parent };
      if (sm) node.shade = { color: sm.color, level: sm.level, token: sm.token };
      parent.children.push(node);
      all.push(node);
      headingStack.push(node);
      listStack = [];
      continue;
    }

    // 목록
    m = line.match(/^([ \t]*)([-*+]|\d+[.)])\s+(.+)$/);
    if (m && m[3].trim() !== '') {
      flush();
      const indentStr = m[1];
      const w = indentWidth(indentStr);
      while (listStack.length && listStack[listStack.length - 1].w >= w) listStack.pop();
      // 빈 줄 뒤에 '같은 깊이 이하'로 돌아온 목록은 본문에서 분리 (띄어 쓰면 별개)
      // 단, 더 깊이 들여쓴 목록은 빈 줄이 있어도 부모(항목/본문)를 유지한다
      if (pendingBlank) popStaleForBlankReturn(w);
      pendingBlank = false;
      let parent;
      // 본문 바로 다음 줄에 붙여 쓴 목록 → 그 본문의 하위단락
      // (본문을 스택 바닥에 기준점으로 깔아서, 같은 급 형제들도 계속 본문 소속이 되게)
      if (lastBody && i === lastBody.endLine + 1 && w >= indentWidth(lastBody.bodyIndent || '')) {
        parent = lastBody;
        // 스택을 통째로 갈아치우지 않고 쌓는다 — 그래야 이 본문의 진짜 조상(예: 이 본문을 담고
        // 있던 목록 항목)이 남아 있어서, 나중에 빈 줄 뒤 형제 문단이 정확한 위치를 찾는다.
        // 이 "바닥" 폭은 본문 자신의 들여쓰기(bodyIndent, 보통 0)로 고정한다 — 예전에는 지금
        // 이 줄(이 붙여쓴 목록의 첫 항목)의 폭에서 1을 뺀 값을 썼는데, 그러면 나중에 이 첫
        // 항목 줄 하나만 탭으로 더 들여써도(형제 항목이나 그 아래 자식 줄은 그대로인데) 바닥
        // 값이 같이 밀려 올라가 버려서, 손대지 않은 형제·자식 줄들의 구조적 깊이(따라서
        // ✓/ㆍ/- 표시)까지 엉뚱하게 바뀌는 문제가 있었다.
        const bodyFloor = indentWidth(lastBody.bodyIndent || '') - 1;
        while (listStack.length && listStack[listStack.length - 1].w >= bodyFloor) listStack.pop();
        listStack.push({ w: bodyFloor, node: lastBody, isBody: true });
      } else {
        parent = listStack.length
          ? listStack[listStack.length - 1].node
          : headingStack[headingStack.length - 1];
      }
      const sm = smmGetShadeInfo(m[3]);
      const nodeText = (sm ? sm.cleanText : m[3]).trim();
      const node = {
        kind: 'list', indentStr, bullet: m[2], text: nodeText,
        line: i, children: [], parent, headingLevel: 99,
      };
      if (sm) node.shade = { color: sm.color, level: sm.level, token: sm.token };
      parent.children.push(node);
      all.push(node);
      listStack.push({ w, node });
      continue;
    }

    if (line.trim() === '') {
      flush(); // 빈 줄 = 문단 구분
      pendingBlank = true;
      continue;
    }
    if (!/^[ \t]/.test(line)) {
      listStack = [];  // 들여쓰기 없는 본문 문단 → 목록 흐름 종료
    } else if (pendingBlank) {
      // 빈 줄 뒤에, 앞선 '본문에 붙여쓴 목록'과 같거나 얕은 깊이로 돌아온 본문 문단은
      // 그 본문의 하위(서브)가 아니라 별개의 새 문단으로 분리한다 (목록 항목에 이미 있는 규칙과 동일)
      const bw = indentWidth((line.match(/^[ \t]*/) || [''])[0]);
      popStaleForBlankReturn(bw);
    }
    pendingBlank = false;
    bufPush(i, line, computeContainer(line));  // 본문 문단 → 메모 노드
    // [변경] 예전엔 빈 줄이 나올 때까지 여러 줄을 한 노드로 묶었는데(문단 단위),
    // 이제는 목록 항목과 똑같이 "엔터(줄바꿈) = 새 노드"로 바로바로 잘라서
    // 편집 화면에서 그냥 엔터 치고 다음 줄에 이어 써도 마인드맵에서 노드가
    // 따로따로 나오게 한다. (코드블록(```)은 별도 분기라 영향 없음 — 그대로 한
    // 덩어리로 유지됨)
    flush();
  }
  flush();

  return { root, all, lines, fmEnd };
}

/** 노드의 마크다운 줄 접두사 (예: "## ", "\t- ") */
function linePrefix(node) {
  if (node.kind === 'heading') return '#'.repeat(node.headingLevel) + ' ';
  if (node.kind === 'list') return node.indentStr + node.bullet + ' ';
  return '';
}

/**
 * 노드가 차지하는 마지막 줄 번호.
 * 제목: 다음 같은/상위 레벨 제목 직전까지(본문 포함).
 * 목록: 자기 하위 노드들의 마지막 줄까지.
 */
function sectionEndLine(node, doc) {
  if (node.kind === 'root') return doc.lines.length - 1;
  if (node.kind === 'heading') {
    for (const n of doc.all) {
      if (n.line > node.line && n.kind === 'heading' && n.headingLevel <= node.headingLevel) {
        return n.line - 1;
      }
    }
    return doc.lines.length - 1;
  }
  let end = node.line;
  const walk = (nd) => {
    const e2 = nd.endLine != null ? nd.endLine : nd.line;
    if (e2 > end) end = e2;
    for (const c of nd.children) walk(c);
  };
  walk(node);
  return end;
}

/** 목록 들여쓰기 한 단계 (탭 문서는 탭, 공백 문서는 4칸) */
function indentUnit(indentStr) {
  return (indentStr.indexOf('\t') === -1 && indentStr.length > 0) ? '    ' : '\t';
}

/** 새 "하위 항목"의 줄 모양 결정 */
/** 새 "하위 항목"의 종류/접두사. 기본은 본문(문단), 이미 있는 형제의 모양을 따라간다. */
function childTemplate(node) {
  let last = null;
  for (let i = node.children.length - 1; i >= 0; i--) {
    if (node.children[i].kind !== 'body') { last = node.children[i]; break; }
  }
  if (node.kind === 'body') {
    // 본문의 하위단락: 문서에서는 그 문단에 붙은 목록 줄
    if (last && last.kind === 'list') return { kind: 'list', prefix: linePrefix(last) };
    return { kind: 'list', prefix: (node.bodyIndent || '') + '- ' };
  }
  if (last) return { kind: last.kind, prefix: linePrefix(last) };
  if (node.kind === 'list') {
    return { kind: 'list', prefix: node.indentStr + indentUnit(node.indentStr) + node.bullet + ' ' };
  }
  // 루트/제목에 아직 아무것도 없으면: 본문(문단)이 기본
  return { kind: 'body', prefix: '' };
}

/**
 * 가지(하위 포함)를 다른 가지 아래로 옮긴 결과를 계산한다.
 * - 제목: 새 부모에 맞춰 제목 레벨(#) 일괄 변환
 * - 목록/메모: 들여쓰기 일괄 변환
 * 반환: { lines, selectLine } 또는 { error } 또는 { noop: true }
 */
function movePlan(doc, node, target, mode) {
  mode = mode || 'child'; // 'child' | 'before' | 'after'
  if (!node || !target) return { error: '옮길 대상이 없어요.' };
  if (node === target) return { noop: true };
  if (node.kind === 'root') return { error: '가운데 노드는 옮길 수 없어요.' };
  if (target.kind === 'root' && mode !== 'child') {
    return { error: '가운데 노드에는 하위로만 붙일 수 있어요.' };
  }
  if (node.path && target.path && (target.path + '.').startsWith(node.path + '.')) {
    return { error: '자기 하위 가지 안으로는 옮길 수 없어요.' };
  }
  const effParent = mode === 'child' ? target : target.parent;
  if (!effParent) return { error: '옮길 위치를 찾지 못했어요.' };

  // 종류 제약
  if (mode === 'child') {
    if (target.kind === 'body' && node.kind === 'heading') {
      return { error: '제목 가지는 본문 아래로 옮길 수 없어요.' };
    }
    if (node.kind === 'heading' && target.kind === 'list') {
      return { error: '제목 가지는 제목이나 가운데 노드 아래로만 옮길 수 있어요.' };
    }
  } else if (node.kind === 'heading' && effParent.kind !== 'root' && effParent.kind !== 'heading') {
    return { error: '제목 가지는 여기에 놓을 수 없어요.' };
  }

  const src = doc.lines;
  const start = node.line;
  const end = sectionEndLine(node, doc);
  const cnt = end - start + 1;
  let block = src.slice(start, end + 1);
  let effKind = node.kind; // 변환 후 실제 삽입되는 종류

  // 블록 변환
  if (node.kind === 'heading') {
    let newLevel;
    if (mode !== 'child' && target.kind === 'heading') {
      newLevel = target.headingLevel; // 형제 = 같은 레벨
    } else {
      newLevel = effParent.kind === 'root' ? 1 : Math.min(effParent.headingLevel + 1, 6);
    }
    const delta = newLevel - node.headingLevel;
    if (delta !== 0) {
      let fence = false;
      block = block.map((l) => {
        if (/^\s*(`{3,}|~{3,})/.test(l)) { fence = !fence; return l; }
        if (fence) return l;
        const m = l.match(/^(#{1,6})(\s+.*)$/);
        if (!m) return l;
        const lv = Math.max(1, Math.min(6, m[1].length + delta));
        return '#'.repeat(lv) + m[2];
      });
    }
  } else if (mode !== 'child' && target.kind === 'heading') {
    // 본문/목록을 제목 앞뒤에 놓으면 그 제목과 '같은 급의 제목'으로 변환
    // (마크다운에서 문단은 항상 앞 제목 소속이라, 등가가 되려면 제목이어야 함)
    const oldBase = node.kind === 'list' ? node.indentStr : (node.bodyIndent || '');
    if (oldBase) {
      block = block.map((l) => (l.trim() === '' ? l : (l.startsWith(oldBase) ? l.slice(oldBase.length) : l)));
    }
    for (let k = 0; k < block.length; k++) {
      if (block[k].trim() === '') continue;
      let t = block[k].replace(/^[ \t]*/, '').replace(/^([-*+]|\d+[.)])\s+/, '');
      block[k] = '#'.repeat(target.headingLevel) + ' ' + t;
      break;
    }
    effKind = 'heading';
  } else if (mode !== 'child' && target.kind === 'list' && node.kind === 'body') {
    // 본문을 목록(하위단락)의 앞뒤에 놓으면 같은 급의 목록 항목으로 변환
    const oldBase = node.bodyIndent || '';
    const newBase = target.indentStr;
    const unit = indentUnit(newBase);
    let first = true;
    block = block.map((l) => {
      if (l.trim() === '') return l;
      const t = l.startsWith(oldBase) ? l.slice(oldBase.length) : l;
      if (first) { first = false; return newBase + target.bullet + ' ' + t; }
      return newBase + unit + t;
    });
    effKind = 'list';
  } else if (mode === 'child' && target.kind === 'body' && node.kind === 'body') {
    // 본문을 본문의 하위로: 하위단락(목록)으로 변환, 하위들은 한 단계 더 들여쓰기
    const oldBase = node.bodyIndent || '';
    const newBase = target.bodyIndent || '';
    const unit = indentUnit(newBase);
    let first = true;
    block = block.map((l) => {
      if (l.trim() === '') return l;
      const t = l.startsWith(oldBase) ? l.slice(oldBase.length) : l;
      if (first) { first = false; return newBase + '- ' + t; }
      return newBase + unit + t;
    });
    effKind = 'list';
  } else {
    const oldBase = node.kind === 'list' ? node.indentStr : (node.bodyIndent || '');
    let newBase;
    if (mode !== 'child' && target.kind === node.kind) {
      newBase = node.kind === 'list' ? target.indentStr : (target.bodyIndent || '');
    } else {
      const ref = mode === 'child' ? target : effParent;
      newBase = ref.kind === 'list' ? ref.indentStr + indentUnit(ref.indentStr)
        : ref.kind === 'body' ? (ref.bodyIndent || '')
        : '';
    }
    if (oldBase !== newBase) {
      block = block.map((l) => {
        if (l.trim() === '') return l;
        return l.startsWith(oldBase) ? newBase + l.slice(oldBase.length) : l;
      });
    }
  }

  // 목록(하위단락, ㆍ/- 표시) 가지를 제목(또는 가운데 노드) 바로 아래 — 즉 0단계(✓)
  // 자리 — 로 옮기면, 첫 줄의 목록 기호("- ")를 떼서 본문 줄로 바꾼다. 마인드맵은
  // 구조로 깊이를 재서 이 자리에서 ✓를 보여주지만, 파일에 "- "가 남아 있으면 편집
  // 화면에서는 옵시디언 글머리(•)로 보여 두 화면이 달랐다("최상위로 옮기면 편집
  // 모드에서도 V 아이콘이 보이도록 점이나 -를 없애" 요청). 번호 목록(1. 2.)은 순서가
  // 뜻이 있으니 그대로 두고, 기호를 떼면 제목/인용/다른 목록/표로 잘못 읽힐 글
  // (#, >, -, 1., |로 시작)도 그대로 둔다. 하위 줄(자식)들은 그대로 두면 이 본문에
  // "붙여 쓴 목록"으로 다시 읽혀, 원래처럼 한 단계 아래(ㆍ)로 남는다.
  let demoteToBody = false;
  if (node.kind === 'list' && effKind === 'list' &&
      !/^\d+[.)]$/.test(node.bullet || '') &&
      (effParent.kind === 'heading' || effParent.kind === 'root')) {
    const k0 = block.findIndex((l) => l.trim() !== '');
    const m0 = k0 >= 0 ? block[k0].match(/^([ \t]*)[-*+][ \t]+(.*)$/) : null;
    if (m0 && m0[2].trim() !== '' && !/^(#{1,6}\s|>|[-*+]\s|\d+[.)]\s|\|)/.test(m0[2])) {
      const lead = m0[1];
      if (lead) {
        block = block.map((l) => (l.trim() !== '' && l.startsWith(lead) ? l.slice(lead.length) : l));
      }
      block[k0] = m0[2];
      demoteToBody = true;
    }
  }

  // 원본에서 제거
  const lines = src.slice();
  lines.splice(start, cnt);
  const adj = (x) => (x > end ? x - cnt : (x >= start ? start - 1 : x));

  // 삽입 위치
  let insertAt;
  if (mode === 'before') {
    insertAt = adj(target.line - 1) + 1;
  } else if (mode === 'after') {
    insertAt = adj(sectionEndLine(target, doc)) + 1;
  } else if (effKind === 'body' && target.kind !== 'body') {
    // 하위로 붙는 본문은 대상 줄 바로 아래 (제목/항목 소속이 되도록)
    insertAt = (target.kind === 'root' ? (doc.fmEnd >= 0 ? doc.fmEnd : -1) : adj(target.line)) + 1;
  } else {
    let a = adj(sectionEndLine(target, doc));
    const tLine = target.kind === 'root' ? -1 : adj(target.line);
    while (a > tLine && a >= 0 && lines[a] != null && lines[a].trim() === '') a--;
    insertAt = a + 1;
  }

  // 빈 줄 규칙
  const arr = [];
  const prev = insertAt - 1 >= 0 ? lines[insertAt - 1] : null;
  const next = lines[insertAt];
  // 본문 줄로 바뀐 목록(demoteToBody)도 본문처럼 앞뒤를 빈 줄로 갈라 둔다 — 안 그러면
  // 바로 위 목록 항목의 "이어지는 글"로 붙거나, 위 본문의 하위로 다시 읽힌다.
  // (삽입 위치 자체는 원래 목록이었을 때와 똑같이 둬서, 마인드맵에서 놓은 순서 그대로.)
  const spacey = effKind === 'heading' || effKind === 'body' || demoteToBody;
  // 목록을 본문 '뒤에(형제)' 놓을 때는 붙으면 하위가 되므로 빈 줄로 분리
  const listGap = effKind === 'list' && mode === 'after' && target.kind === 'body';
  if ((spacey || listGap) && prev != null && prev.trim() !== '') arr.push('');
  const lead = arr.length;
  arr.push(...block);
  if ((effKind === 'body' || demoteToBody) && next != null && next.trim() !== '') arr.push('');
  lines.splice(insertAt, 0, ...arr);

  return { lines, selectLine: insertAt + lead };
}

/**
 * 연속된 빈 줄을 한 줄로 정리한다 (코드 블록 안은 보존).
 * trackLine을 주면 정리 후 그 줄의 새 위치를 함께 돌려준다.
 */
function collapseBlankRuns(lines, trackLine) {
  const out = [];
  let prevBlank = false;
  let inFence = false;
  let tracked = trackLine != null ? -1 : null;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (/^\s*(`{3,}|~{3,})/.test(line)) inFence = !inFence;
    const b = !inFence && line.trim() === '';
    if (b && prevBlank && trackLine !== i) continue; // 연속 빈 줄 제거
    if (trackLine === i) tracked = out.length;
    out.push(line);
    prevBlank = b;
  }
  if (trackLine != null && tracked === -1) tracked = Math.min(trackLine, Math.max(out.length - 1, 0));
  return { lines: out, line: tracked };
}

/** 노드의 '자기 줄'을 다른 텍스트로 다시 쓴 결과 (종류/접두사/들여쓰기는 유지) */
function ownLinesFor(node, text) {
  const shadeSuffix = (node && node.shade && node.shade.token) ? (' ' + node.shade.token) : '';
  if (node.kind === 'heading') {
    const t = text.split('\n').map((s) => s.trim()).filter(Boolean).join('<br>');
    return ['#'.repeat(node.headingLevel) + ' ' + t + shadeSuffix];
  }
  if (node.kind === 'list') {
    const t = text.split('\n').map((s) => s.trim()).filter(Boolean).join('<br>');
    return [node.indentStr + node.bullet + ' ' + t + shadeSuffix];
  }
  const ind = node.bodyIndent || '';
  const lines = text.split('\n').map((l) => (l.trim() === '' ? '' : ind + l));
  if (shadeSuffix && lines.length > 0) {
    lines[lines.length - 1] += shadeSuffix;
  }
  return lines;
}

/**
 * 두 가지의 '내용'을 맞바꾼 결과. 구조(하위 가지, 종류, 위치)는 그대로 두고
 * 글만 서로 교환한다. 부모↔자식 자리 바꾸기에 특히 유용.
 */
function swapPlan(doc, a, b) {
  if (!a || !b || a === b) return { error: '맞바꿀 두 가지를 확인해 주세요.' };
  if (a.kind === 'root' || b.kind === 'root') return { error: '가운데 노드는 맞바꿀 수 없어요.' };
  const lines = doc.lines.slice();
  const segs = [
    { s: a.line, e: a.kind === 'body' ? a.endLine : a.line, repl: ownLinesFor(a, b.text) },
    { s: b.line, e: b.kind === 'body' ? b.endLine : b.line, repl: ownLinesFor(b, a.text) },
  ].sort((x, y) => y.s - x.s); // 뒤쪽부터 치환해야 줄 번호가 안 밀림
  for (const g of segs) lines.splice(g.s, g.e - g.s + 1, ...g.repl);
  return { lines, selectLine: Math.min(a.line, b.line) };
}

/**
 * 노드의 섹션 끝에 새 항목을 삽입한 결과를 계산한다.
 * spec = { kind: 'heading'|'list'|'body', prefix }
 * 섹션 끝의 빈 줄들은 건너뛰고 마지막 내용 줄 바로 뒤에 넣는다.
 * 제목/본문은 빈 줄로 구분해 넣고, 목록은 붙여 넣는다.
 */
function insertPlan(doc, node, spec) {
  const lines = doc.lines.slice();
  let anchor = sectionEndLine(node, doc);
  const minLine = node.kind === 'root' ? -1 : node.line;
  while (anchor > minLine && anchor >= 0 && (lines[anchor] == null || lines[anchor].trim() === '')) {
    anchor--;
  }
  const toInsert = [];
  const needBlank = spec.kind === 'heading' || spec.kind === 'body';
  if (needBlank && anchor >= 0 && lines[anchor] != null && lines[anchor].trim() !== '') {
    toInsert.push('');
  }
  toInsert.push(spec.prefix + (spec.kind === 'body' ? NEW_BODY : NEW_TEXT));
  lines.splice(anchor + 1, 0, ...toInsert);
  return { lines, newLine: anchor + toInsert.length };
}

/* ================= 노드 안 마크다운 꾸밈 렌더링 ================= */

function escapeHtml(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/** 마인드맵 노드 안의 ==강조==를 편집 화면과 같은 색으로 칠한다.
 *  styles.css·테마 규칙이 !important 로 다른 색(연두 등)을 입혀도 지지 않도록 인라인 !important 로 지정한다.
 *  색은 highlight.css 의 변수(--hl-*)를 따르고, 그 스니펫이 꺼져 있으면 아래 기본값을 쓴다.
 *  장절 배지("(책 장:절)"만으로 이뤄진 mark)는 건드리지 않는다. */
const SMM_HL_FALLBACK = {
  red: ['#FFC2C2', 'rgba(235, 87, 87, 0.42)'], orange: ['#FFD6A5', 'rgba(242, 153, 74, 0.42)'],
  yellow: ['#FFF3A3', 'rgba(242, 201, 76, 0.35)'], green: ['#BFEBC4', 'rgba(111, 207, 151, 0.42)'],
  blue: ['#BDE0FF', 'rgba(86, 204, 242, 0.42)'], purple: ['#DCCBFF', 'rgba(155, 81, 224, 0.42)'],
};
function smmStyleMark(m, dark) {
  const txt = (m.textContent || '').trim();
  if (txt && txt.replace(SMR_VERSE_REF_RE, '').trim() === '') return;   // 장절 배지
  const key = m.getAttribute('data-highlight');
  const fb = key && SMM_HL_FALLBACK[key];
  const bg = fb ? `var(--hl-${key}-bg, ${fb[dark ? 1 : 0]})`
                : `var(--hl-default-bg, ${dark ? 'rgba(242, 201, 76, 0.35)' : '#fef2a0'})`;
  const color = fb ? 'inherit' : `var(--hl-default-text, ${dark ? 'inherit' : '#595217'})`;
  m.style.setProperty('background-color', bg, 'important');
  m.style.setProperty('color', color, 'important');
  m.style.setProperty('border-radius', '3px');
  m.style.setProperty('padding', '0 2px');
}
function smmStyleHighlights(root) {
  if (!root || !root.querySelectorAll) return;
  const dark = !!(document.body && document.body.classList.contains('theme-dark'));
  root.querySelectorAll('mark').forEach((m) => smmStyleMark(m, dark));
}
// 옵시디언 1.14 색상 강조(==🔴 글자==)의 이모지 → 색 이름. 편집 화면·읽기 화면의 mark[data-highlight]와 같은 이름.
const SMM_HL_KEYS = { '🔴': 'red', '🟠': 'orange', '🟡': 'yellow', '🟢': 'green', '🔵': 'blue', '🟣': 'purple' };
const SMM_HL_EMOJI_RE = /^(\u{1F534}|\u{1F7E0}|\u{1F7E1}|\u{1F7E2}|\u{1F535}|\u{1F7E3})\uFE0F?[ \t]?/u;

/** 색 하이라이트를 아직 모르는 옛 옵시디언(예: 아이패드 앱)은 ==🔴 글자== 를 노란 mark 안에 이모지 글자로 그린다.
 *  그걸 <mark data-highlight="red">글자</mark> 로 바로잡고(이모지 제거), 고친 mark 목록을 돌려준다.
 *  색 하이라이트를 아는 옵시디언(PC 1.14+)은 이미 data-highlight 가 있어서 아무것도 하지 않는다. */
function smmNormalizeColorMarks(root) {
  const fixed = [];
  try {
    if (!root || !root.querySelectorAll || typeof document === 'undefined') return fixed;
    root.querySelectorAll('mark:not([data-highlight])').forEach((m) => {
      const tn = document.createTreeWalker(m, NodeFilter.SHOW_TEXT).nextNode();
      if (!tn) return;
      const mm = String(tn.nodeValue || '').match(SMM_HL_EMOJI_RE);
      if (!mm) return;
      tn.nodeValue = tn.nodeValue.slice(mm[0].length);
      m.setAttribute('data-highlight', SMM_HL_KEYS[mm[1]]);
      fixed.push(m);
    });
  } catch (e) { /* 무시 */ }
  return fixed;
}
/** 바로잡은 mark 에는 색도 바로 입힌다(스니펫이 꺼져 있어도 같은 색이 나오도록) */
function smmFixColorMarks(root) {
  const fixed = smmNormalizeColorMarks(root);
  const dark = !!(document.body && document.body.classList.contains('theme-dark'));
  fixed.forEach((m) => smmStyleMark(m, dark));
  return fixed.length;
}

/* ===== 옛 옵시디언의 편집 화면: ==🔴 글자== 를 색으로 보이게 하고 이모지는 숨긴다 =====
 * 색 하이라이트를 아는 옵시디언(PC 1.14+)은 스스로 처리하므로 건드리지 않는다.
 * 아는지는 시작할 때 한 번 시험 렌더링으로 확인한다(smmDetectNativeColorHighlight). */
let SMM_NATIVE_COLOR_HL = null; // null=아직 모름(→ 건드리지 않음), true=옵시디언이 직접 처리, false=이 플러그인이 대신 처리

async function smmDetectNativeColorHighlight(plugin) {
  let native = null;
  try {
    const host = document.createElement('div');
    plugin._smrRenderDepth = (plugin._smrRenderDepth || 0) + 1; // 우리 후처리기가 결과를 고쳐 버리지 않게
    try { await MarkdownRenderer.render(plugin.app, '==\u{1F534} x==', host, '', plugin); }
    finally { plugin._smrRenderDepth = Math.max(0, (plugin._smrRenderDepth || 1) - 1); }
    const m = host.querySelector('mark');
    if (m) native = m.hasAttribute('data-highlight') || !/^\s*(\u{1F534}|\u{1F7E0}|\u{1F7E1}|\u{1F7E2}|\u{1F535}|\u{1F7E3})/u.test(m.textContent || '');
  } catch (e) { native = null; }
  if (native === null) { // 시험이 안 되면 버전으로 추정(색 하이라이트는 1.14부터)
    const v = String(obsidian.apiVersion || '').split('.').map((x) => parseInt(x, 10) || 0);
    native = v[0] > 1 || (v[0] === 1 && v[1] >= 14);
  }
  const changed = SMM_NATIVE_COLOR_HL !== native;
  SMM_NATIVE_COLOR_HL = native;
  if (changed) { try { plugin.app.workspace.updateOptions(); } catch (e) { /* 무시 */ } }
  return native;
}

function smmEnsureHlStyle() {
  if (typeof document === 'undefined' || document.getElementById('smm-hl-style')) return;
  const light = { red: '#FFC2C2', orange: '#FFD6A5', yellow: '#FFF3A3', green: '#BFEBC4', blue: '#BDE0FF', purple: '#DCCBFF' };
  const darkc = { red: 'rgba(235, 87, 87, 0.42)', orange: 'rgba(242, 153, 74, 0.42)', yellow: 'rgba(242, 201, 76, 0.35)', green: 'rgba(111, 207, 151, 0.42)', blue: 'rgba(86, 204, 242, 0.42)', purple: 'rgba(155, 81, 224, 0.42)' };
  let css = '.smm-hlc{border-radius:4px;padding:0 4px;color:inherit !important;}\n'
    // 옛 옵시디언이 같은 글에 깔아 두는 노란 .cm-highlight 는 투명하게 — 안쪽(또는 바깥) 색 칸만 보이게
    // (highlight.css 의 기본 강조 규칙보다 우선하도록 선택자를 길게 씀)
    + '.markdown-source-view.mod-cm6 .cm-editor .cm-highlight:has(.smm-hlc):not([data-highlight]):not([class*="cm-highlight-"]),'
    + '.markdown-source-view.mod-cm6 .cm-editor .smm-hlc .cm-highlight:not([data-highlight]):not([class*="cm-highlight-"])'
    + '{background:transparent !important;padding:0 !important;color:inherit !important;box-shadow:none !important;}\n';
  for (const k of Object.keys(light)) {
    css += `.smm-hlc-${k}{background-color:var(--hl-${k}-bg,${light[k]}) !important;}\n`
        +  `body.theme-dark .smm-hlc-${k}{background-color:var(--hl-${k}-bg,${darkc[k]}) !important;}\n`;
  }
  const st = document.createElement('style');
  st.id = 'smm-hl-style';
  st.textContent = css;
  document.head.appendChild(st);
}

function smmBuildColorHighlightExtension(plugin) {
  let cmView, cmState;
  try { cmView = require('@codemirror/view'); cmState = require('@codemirror/state'); } catch (e) { return null; }
  if (!cmView || !cmState) return null;
  const { ViewPlugin, Decoration } = cmView;
  const { RangeSetBuilder } = cmState;
  if (!ViewPlugin || !Decoration || !RangeSetBuilder) return null;
  // `코드` 는 건너뛰고, ==이모지 글자== 만 찾는다 (이모지 1개 + 선택 공백 + 글자)
  const RE = /(`[^`\n]*`)|==(\u{1F534}|\u{1F7E0}|\u{1F7E1}|\u{1F7E2}|\u{1F535}|\u{1F7E3})\uFE0F?([ \t]?)((?:(?!==)[^\n])+?)==/gu;
  const build = (view) => {
    const b = new RangeSetBuilder();
    try {
      if (SMM_NATIVE_COLOR_HL !== false) return b.finish();
      const doc = view.state.doc;
      const sel = view.state.selection.ranges;
      for (const { from, to } of view.visibleRanges) {
        let pos = from;
        while (pos <= to) {
          const line = doc.lineAt(pos);
          RE.lastIndex = 0;
          let m;
          while ((m = RE.exec(line.text))) {
            if (m[1]) continue;
            const start = line.from + m.index;
            const end = start + m[0].length;
            const key = SMM_HL_KEYS[m[2]];
            b.add(start, end, Decoration.mark({ class: 'smm-hlc smm-hlc-' + key }));
            const prefixLen = m[0].length - 4 - m[4].length;           // 이모지(+변형선택자)(+공백)
            const editing = sel.some((r) => r.from <= end && r.to >= start); // 커서가 안에 있으면 이모지를 보여 준다
            if (!editing && prefixLen > 0) b.add(start + 2, start + 2 + prefixLen, Decoration.replace({}));
          }
          if (line.to + 1 <= pos) break;
          pos = line.to + 1;
        }
      }
    } catch (e) { /* 색을 못 입혀도 편집은 계속 되어야 함 */ }
    return b.finish();
  };
  return ViewPlugin.fromClass(
    class {
      constructor(view) { this.decorations = build(view); }
      update(u) { if (u.docChanged || u.viewportChanged || u.selectionSet) this.decorations = build(u.view); }
    },
    { decorations: (v) => v.decorations }
  );
}
function renderInline(raw) {
  let t = raw;
  let prefixHtml = '';
  const cb = t.match(/^\[( |x|X)\]\s+(.*)$/); // 체크박스
  if (cb) { prefixHtml = cb[1] === ' ' ? '☐ ' : '☑ '; t = cb[2]; }
  
  const tempMarks = [];
  t = t.replace(/<mark([^>]*)>([\s\S]*?)<\/mark>/g, (m, p1, p2) => {
    tempMarks.push({ p1, p2 });
    return `MARK${tempMarks.length - 1}`;
  });
  t = escapeHtml(t);
  t = t.replace(/`([^`]+)`/g, '<code>$1</code>');
  t = t.replace(/==([^=]+)==/g, (m, inner) => {
    const hm = inner.match(/^(\u{1F534}|\u{1F7E0}|\u{1F7E1}|\u{1F7E2}|\u{1F535}|\u{1F7E3})[ \t]?/u);
    if (!hm) return `<mark>${inner}</mark>`;
    return `<mark data-highlight="${SMM_HL_KEYS[hm[1]]}">${inner.slice(hm[0].length)}</mark>`;
  });
  t = t.replace(/MARK(\d+)/g, (m, i) => {
    const tm = tempMarks[i];
    return `<mark${tm.p1}>${escapeHtml(tm.p2)}</mark>`;
  });
  t = t.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  t = t.replace(/__([^_]+)__/g, '<strong>$1</strong>');
  t = t.replace(/(^|[^*])\*([^*]+)\*/g, '$1<em>$2</em>');
  t = t.replace(/(^|[^_\w])_([^_]+)_/g, '$1<em>$2</em>');
  t = t.replace(/~~([^~]+)~~/g, '<del>$1</del>');
  t = t.replace(/&lt;u&gt;([\s\S]*?)&lt;\/u&gt;/g, '<u>$1</u>');
  t = t.replace(/!?\[\[([^\]|]+)\|([^\]]+)\]\]/g, '<span class="smm-link">$2</span>');
  t = t.replace(/!?\[\[([^\]]+)\]\]/g, '<span class="smm-link">$1</span>');
  t = t.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<span class="smm-link">$1</span>');
  return prefixHtml + t;
}

function descCount(node) {
  let n = 0;
  const walk = (nd) => { for (const c of nd.children) { n++; walk(c); } };
  walk(node);
  return n;
}



/* ========== ZIP (무압축 저장) ========== */

let CRC_TABLE = null;
function crc32(buf) {
  if (!CRC_TABLE) {
    CRC_TABLE = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
      CRC_TABLE[n] = c >>> 0;
    }
  }
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function zipStore(files) {
  const enc = new TextEncoder();
  const chunks = [];
  const central = [];
  let offset = 0;
  const u16 = (v) => new Uint8Array([v & 255, (v >> 8) & 255]);
  const u32 = (v) => new Uint8Array([v & 255, (v >> 8) & 255, (v >> 16) & 255, (v >>> 24) & 255]);
  for (const f of files) {
    const name = enc.encode(f.name);
    const data = typeof f.data === 'string' ? enc.encode(f.data) : f.data;
    const crc = crc32(data);
    const head = [
      u32(0x04034b50), u16(20), u16(0x0800), u16(0), u16(0), u16(0x5821),
      u32(crc), u32(data.length), u32(data.length), u16(name.length), u16(0),
    ];
    const local = concatBytes([...head, name, data]);
    chunks.push(local);
    central.push({ name, data, crc, offset });
    offset += local.length;
  }
  const cd = [];
  for (const e of central) {
    cd.push(concatBytes([
      u32(0x02014b50), u16(20), u16(20), u16(0x0800), u16(0), u16(0), u16(0x5821),
      u32(e.crc), u32(e.data.length), u32(e.data.length), u16(e.name.length),
      u16(0), u16(0), u16(0), u16(0), u32(0), u32(e.offset), e.name,
    ]));
  }
  const cdBytes = concatBytes(cd);
  const eocd = concatBytes([
    u32(0x06054b50), u16(0), u16(0), u16(central.length), u16(central.length),
    u32(cdBytes.length), u32(offset), u16(0),
  ]);
  return concatBytes([...chunks, cdBytes, eocd]);
}

function concatBytes(arrs) {
  let len = 0;
  for (const a of arrs) len += a.length;
  const out = new Uint8Array(len);
  let p = 0;
  for (const a of arrs) { out.set(a, p); p += a.length; }
  return out;
}

/* ========== 서식 상수 (원고 내보내기 기본값 — 설정에서 바꿀 수 있음) ========== */

