  // ---- 설교문 읽기 모드(강대상용) ----
  rdTheme: '자동',      // 자동(옵시디언 테마 따름) / 밝게 / 어둡게
  rdFontBody: '',       // 비어있으면 옵시디언 본문 글꼴
  rdSizeBody: 26,       // px
  rdLineHeight: 1.75,
  rdParaGap: 0.7,       // em (문단 사이 간격)
  rdIndent: 0.5,        // 글자 수. 목록이 한 단계 내려갈 때마다 들여쓰는 폭
  // 들여쓰기 없는(0단계) 줄의 ✓ 표시 — 위 markStrong*와는 독립(이 화면 전용)
  rdMarkColor: 'BF4E14',  // ✓ 아이콘 색
  rdMarkScale: '',         // ✓ 아이콘 크기 배율(em). 비어있으면 1.1(기존)
  rdMarkLineColor: '',     // ✓ 줄 글자색. 비어있으면 본문 색 그대로
  rdMarkLineFont: '',      // ✓ 줄 글자 폰트. 비어있으면 본문 글꼴 그대로
  rdMarkLineScale: '',     // ✓ 줄 글자 크기 배율(em). 비어있으면 1(본문과 같게)
  rdFontHead: '',       // 비어있으면 본문 글꼴과 같게
  rdFontVerse: '',      // 인용글(성경구절) 글꼴. 비어있으면 아래 토글에 따름
  rdSizeH1: '', rdSizeH2: '', rdSizeH3: '', rdSizeH4: '', rdSizeH5: '', rdSizeH6: '',
  // 제목 1~6 색. 비어있으면 밝게/어둡게 모드 기본값을 그대로 씀(smrStyleVars 참고)
  rdColorH1: '', rdColorH2: '', rdColorH3: '', rdColorH4: '', rdColorH5: '', rdColorH6: '',
  rdColorDarkH1: '', rdColorDarkH2: '', rdColorDarkH3: '', rdColorDarkH4: '', rdColorDarkH5: '', rdColorDarkH6: '', // 어두운 테마 전용 제목 색(비우면 기본값)
  rdMargin: 24,         // px 페이지 여백
  rdMaxWidth: 1300,     // px 글줄 최대 폭 (0이면 화면 전체)
  rdVerseFont: true,    // 성경구절에 "성경구절 폰트"를 함께 쓰기
  rdScroll: false,      // 위아래 스크롤 모드(장 나누지 않고 쭉 보기)
  rdAnim: true,         // 넘길 때 밀리는 움직임
  rdShowPage: true,     // 아래쪽 쪽 표시
  rdLockDrawer: true,   // 읽기 모드에서 좌우로 밀 때 옆 서랍(사이드바)이 딸려 나오지 않게
  // 설교문 미리보기 펜슬 필기(아이패드 전용)
  inkEnabled: true,     // 아이패드에서 펜슬 필기 도구를 보여줄지
  inkFolder: '_설교마인드맵_필기', // 필기 저장 폴더(보관함 안)
  inkTool: 'hl',        // 마지막으로 쓴 도구: hl(형광펜) ul(밑줄) pen(판서) eraser(지우개)
  inkColors: {},        // 도구별 마지막 색
  inkBarOpen: false,    // 도구 막대를 펼쳐 둔 상태(펼쳤을 때만 펜슬이 필기함)
  inkHidden: false,     // 필기 숨기기
  rdSpaceMigrated: false, // 여백 기본값을 한 번 새로 맞췄는지 (내부용)
  // 번들 글꼴(위 rdFontBody 등에 이름만 적어 둔 글꼴의 실제 파일)을 넣어 두는 보관함
  // 안의 폴더. 플러그인 폴더 안이 아니라 "보관함(vault) 안" 폴더여야 옵시디언 Sync가
  // 보통 파일처럼 옮겨줘서 아이패드 등에서도 똑같이 받아짐.
  rdFontFolder: '_설교마인드맵_글꼴',
