    '--smr-size-h2': n(s.rdSizeH2, Math.round(body * 1.34)) + 'px',
    '--smr-size-h3': n(s.rdSizeH3, Math.round(body * 1.18)) + 'px',
    '--smr-size-h4': n(s.rdSizeH4, Math.round(body * 1.08)) + 'px',
